  const gap = 120; // gap width for player to pass
  const left = Math.random() * (W - gap - 40) + 20;
  const right = left + gap;
  walls.push({ x: 0, y: yPos, w: left, h: 20 }); // left wall
  walls.push({ x: right, y: yPos, w: W - right, h: 20 }); // right wall
